            { kind = "heading", text = "Class or GENERAL" },
            { kind = "para", text = "A |cffa8d8ffGENERAL|r template exists on every character; a class template only on characters of that class. Two templates of the same class cannot share a name, and a |cffa8d8ffGENERAL|r name is taken for every class." },
