            { kind = "heading", text = "Arenas" },
            { kind = "list", ordered = false, items = { "|cffa8d8ffARENA1|r–|cffa8d8ffARENA5|r are the classes in each enemy slot. |cffa8d8ffCOMP=ROGUE|r is true if any opponent is a rogue; |cffa8d8ffCOMP=ROGUE AND COMP=PRIEST|r needs both.", "A slot stays known while its player is stealthed or out of sight.", "|cffffd100Placeholders|r write the opponent into the macro. |cffa8d8ffROGUE|r becomes the slot holding a rogue (|cffa8d8ffarena1|r, …), |cffa8d8ffROGUE#2|r the second rogue, |cffa8d8ffROGUEPET|r its pet, and |cffa8d8ffNOTROGUE|r the first opponent known not to be a rogue. Use them as |cffa8d8ff[@ROGUE]|r, or bare and in capitals: |cffa8d8ff/focus ROGUE|r. Lowercase words are never replaced, so |cffa8d8ff/say rogue on me|r stays as written.", "A placeholder that finds no one becomes |cffa8d8ffarena0|r, which never matches, so that line simply does nothing." } },
            { kind = "code", source = "#WATCH ARENA\n\n#DEFAULT\n/focus arena1\n\n#IF[10] COMP=PRIEST\n/focus PRIEST\n\n#IF COMP=ROGUE\n/focus NOTROGUE" },
            { kind = "para", text = "Focus the priest; against a rogue without a priest, focus the rogue's partner. With both on the team, both |cffa8d8ff#IF|rs match with one test each, and |cffa8d8ff[10]|r makes the priest version win instead of an error." },
            { kind = "try", text = "|cffd0c8b0Try it|r — Preview as |cffa8d8ffARENA1=ROGUE ARENA2=PRIEST|r, then |cffa8d8ffARENA1=ROGUE ARENA2=MAGE|r.", example = 1, states = { "ARENA1=ROGUE ARENA2=PRIEST", "ARENA1=ROGUE ARENA2=MAGE" } },
            { kind = "heading", text = "Duels" },
