            { kind = "list", ordered = false, items = { "|cffa8d8ff.TIME|r takes |cffa8d8ff<|r, |cffa8d8ff<=|r, |cffa8d8ff>|r or |cffa8d8ff>=|r and an amount with a unit: |cffa8d8ff90s|r, |cffa8d8ff15m|r, |cffa8d8ff1h|r.", "|cffa8d8ff.STACKS|r takes a number: |cffa8d8ffAURA:SELF:\"DEADLY POISON\".STACKS>=5|r.", "A missing aura has no time, so |cffa8d8ff.TIME<5m|r alone does not match when the buff is gone. Test both, as above." } },
